'use strict';

// MODULES //

var tape = require( 'tape' );
var toAccessorArray = require( '@stdlib/array/base/to-accessor-array' );
var gsearchSorted = require( './../lib/ndarray.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof gsearchSorted, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 12', function test( t ) {
	t.strictEqual( gsearchSorted.length, 12, 'has expected arity' );
	t.end();
});

tape( 'the function throws an error if provided an invalid `side` argument', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		'abc',
		'LEFT',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			gsearchSorted( 1, 3, value, [ 2.0 ], 1, 0, [ 1.0, 2.0, 3.0 ], 1, 0, [ 0 ], 1, 0 ); // eslint-disable-line max-len
		};
	}
});

tape( 'the function finds left insertion indices (ascending order)', function test( t ) {
	var expected;
	var search;
	var out;
	var x;

	search = [ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0 ];
	x = [ 0.0, 1.0, 2.0, 2.5, 3.0, 4.0 ];
	out = [ 0, 0, 0, 0, 0, 0 ];

	gsearchSorted( x.length, search.length, 'left', x, 1, 0, search, 1, 0, out, 1, 0 );

	expected = [ 0, 0, 2, 4, 4, 6 ];
	t.deepEqual( out, expected, 'returns expected value' );

	t.end();
});

