tape( 'if provided an `M` parameter less than or equal to `0`, the function returns the output array unchanged', function test( t ) {
	var expected;
	var out;

	out = [ 9, 9, 9 ];
	expected = [ 9, 9, 9 ];

	gsearchSorted( 0, 3, 'left', [ 1.0, 2.0, 3.0 ], 1, 0, [ 1.0, 2.0, 3.0 ], 1, 0, out, 1, 0 );
	t.deepEqual( out, expected, 'returns expected value' );

	gsearchSorted( -1, 3, 'left', [ 1.0, 2.0, 3.0 ], 1, 0, [ 1.0, 2.0, 3.0 ], 1, 0, out, 1, 0 );
	t.deepEqual( out, expected, 'returns expected value' );

	t.end();
});

tape( 'if provided an `N` parameter less than or equal to `0`, the function sets each output element to `0` (or `-1` for `NaN` search elements)', function test( t ) {
	var expected;
	var out;

	out = [ 9, 9, 9 ];
	expected = [ 0, 0, 0 ];

	gsearchSorted( 3, 0, 'left', [ 1.0, 2.0, 3.0 ], 1, 0, [], 1, 0, out, 1, 0 );
	t.deepEqual( out, expected, 'returns expected value' );

	out = [ 9, 9, 9 ];
	gsearchSorted( 3, -1, 'right', [ 1.0, 2.0, 3.0 ], 1, 0, [], 1, 0, out, 1, 0 );
	t.deepEqual( out, expected, 'returns expected value' );

	// `NaN` search elements:
	out = [ 9, 9, 9 ];
	gsearchSorted( 3, 0, 'left', [ NaN, 2.0, NaN ], 1, 0, [], 1, 0, out, 1, 0 );
	t.deepEqual( out, [ -1, 0, -1 ], 'returns expected value' );

	// Accessor arrays:
	out = [ 9, 9, 9 ];
	gsearchSorted( 3, 0, 'right', toAccessorArray( [ NaN, 2.0, 3.0 ] ), 1, 0, toAccessorArray( [] ), 1, 0, toAccessorArray( out ), 1, 0 );
	t.deepEqual( out, [ -1, 0, 0 ], 'returns expected value' );

	t.end();
});

tape( 'the function writes `-1` for `NaN` search elements', function test( t ) {
	var out;

	// Ascending order:
	out = [ 0, 0, 0 ];
	gsearchSorted( 3, 3, 'left', [ NaN, 2.0, NaN ], 1, 0, [ 1.0, 2.0, 3.0 ], 1, 0, out, 1, 0 );
	t.deepEqual( out, [ -1, 1, -1 ], 'returns expected value' );

	out = [ 0, 0, 0 ];
	gsearchSorted( 3, 3, 'right', [ NaN, 2.0, NaN ], 1, 0, [ 1.0, 2.0, 3.0 ], 1, 0, out, 1, 0 );
	t.deepEqual( out, [ -1, 2, -1 ], 'returns expected value' );

	// Descending order:
	out = [ 0, 0, 0 ];
	gsearchSorted( 3, 3, 'left', [ NaN, 2.0, NaN ], 1, 0, [ 3.0, 2.0, 1.0 ], 1, 0, out, 1, 0 );
	t.deepEqual( out, [ -1, 1, -1 ], 'returns expected value' );

	out = [ 0, 0, 0 ];
	gsearchSorted( 3, 3, 'right', [ NaN, 2.0, NaN ], 1, 0, [ 3.0, 2.0, 1.0 ], 1, 0, out, 1, 0 );
	t.deepEqual( out, [ -1, 2, -1 ], 'returns expected value' );

	// Sorted array containing `NaN` values:
	out = [ 0, 0, 0 ];
	gsearchSorted( 3, 3, 'left', [ NaN, 2.0, NaN ], 1, 0, [ 1.0, NaN, 3.0 ], 1, 0, out, 1, 0 );
	t.deepEqual( out, [ -1, 2, -1 ], 'returns expected value' );

	t.end();
});

tape( 'the function writes `-1` for `NaN` search elements (accessors)', function test( t ) {
	var out;

	// Ascending order:
	out = [ 0, 0, 0 ];
	gsearchSorted( 3, 3, 'left', toAccessorArray( [ NaN, 2.0, NaN ] ), 1, 0, toAccessorArray( [ 1.0, 2.0, 3.0 ] ), 1, 0, toAccessorArray( out ), 1, 0 );
	t.deepEqual( out, [ -1, 1, -1 ], 'returns expected value' );

	out = [ 0, 0, 0 ];
	gsearchSorted( 3, 3, 'right', toAccessorArray( [ NaN, 2.0, NaN ] ), 1, 0, toAccessorArray( [ 1.0, 2.0, 3.0 ] ), 1, 0, toAccessorArray( out ), 1, 0 );
	t.deepEqual( out, [ -1, 2, -1 ], 'returns expected value' );

	// Descending order:
	out = [ 0, 0, 0 ];
	gsearchSorted( 3, 3, 'left', toAccessorArray( [ NaN, 2.0, NaN ] ), 1, 0, toAccessorArray( [ 3.0, 2.0, 1.0 ] ), 1, 0, toAccessorArray( out ), 1, 0 );
	t.deepEqual( out, [ -1, 1, -1 ], 'returns expected value' );

	out = [ 0, 0, 0 ];
	gsearchSorted( 3, 3, 'right', toAccessorArray( [ NaN, 2.0, NaN ] ), 1, 0, toAccessorArray( [ 3.0, 2.0, 1.0 ] ), 1, 0, toAccessorArray( out ), 1, 0 );
	t.deepEqual( out, [ -1, 2, -1 ], 'returns expected value' );

	// Sorted array containing `NaN` values:
	out = [ 0, 0, 0 ];
	gsearchSorted( 3, 3, 'left', toAccessorArray( [ NaN, 2.0, NaN ] ), 1, 0, toAccessorArray( [ 1.0, NaN, 3.0 ] ), 1, 0, toAccessorArray( out ), 1, 0 );
	t.deepEqual( out, [ -1, 2, -1 ], 'returns expected value' );

	t.end();
});

tape( 'the function supports sorted arrays containing `NaN` values', function test( t ) {
	var search;
	var out;

	search = [ 1.0, NaN, 3.0, 4.0 ];

	out = [ 0 ];
	gsearchSorted( 1, search.length, 'left', [ 3.0 ], 1, 0, search, 1, 0, out, 1, 0 );
	t.deepEqual( out, [ 2 ], 'returns expected value' );

	out = [ 0 ];
	gsearchSorted( 1, search.length, 'right', [ 3.0 ], 1, 0, search, 1, 0, out, 1, 0 );
	t.deepEqual( out, [ 3 ], 'returns expected value' );

	search = [ NaN, 1.0, 2.0, 3.0 ];

	out = [ 0 ];
	gsearchSorted( 1, search.length, 'left', [ 2.0 ], 1, 0, search, 1, 0, out, 1, 0 );
	t.deepEqual( out, [ 2 ], 'returns expected value' );

	out = [ 0 ];
	gsearchSorted( 1, search.length, 'right', [ 2.0 ], 1, 0, search, 1, 0, out, 1, 0 );
	t.deepEqual( out, [ 3 ], 'returns expected value' );

	search = [ 1.0, 2.0, 3.0, NaN ];

	out = [ 0 ];
	gsearchSorted( 1, search.length, 'left', [ 2.0 ], 1, 0, search, 1, 0, out, 1, 0 );
	t.deepEqual( out, [ 1 ], 'returns expected value' );

	out = [ 0 ];
	gsearchSorted( 1, search.length, 'right', [ 2.0 ], 1, 0, search, 1, 0, out, 1, 0 );
	t.deepEqual( out, [ 2 ], 'returns expected value' );

	search = [ NaN, NaN ];

	out = [ 0 ];
	gsearchSorted( 1, search.length, 'left', [ 2.0 ], 1, 0, search, 1, 0, out, 1, 0 );
	t.deepEqual( out, [ 2 ], 'returns expected value' );

	// Descending order:
	search = [ 3.0, NaN, 2.0, 1.0 ];

	out = [ 0 ];
	gsearchSorted( 1, search.length, 'left', [ 2.0 ], 1, 0, search, 1, 0, out, 1, 0 );
	t.deepEqual( out, [ 2 ], 'returns expected value' );

	out = [ 0 ];
	gsearchSorted( 1, search.length, 'right', [ 2.0 ], 1, 0, search, 1, 0, out, 1, 0 );
	t.deepEqual( out, [ 3 ], 'returns expected value' );

	t.end();
});

tape( 'the function supports sorted arrays containing `NaN` values (accessors)', function test( t ) {
	var search;
	var out;

	search = toAccessorArray( [ 1.0, NaN, 3.0, 4.0 ] );

	out = [ 0 ];
	gsearchSorted( 1, search.length, 'left', toAccessorArray( [ 3.0 ] ), 1, 0, search, 1, 0, toAccessorArray( out ), 1, 0 );
	t.deepEqual( out, [ 2 ], 'returns expected value' );

	out = [ 0 ];
	gsearchSorted( 1, search.length, 'right', toAccessorArray( [ 3.0 ] ), 1, 0, search, 1, 0, toAccessorArray( out ), 1, 0 );
	t.deepEqual( out, [ 3 ], 'returns expected value' );

	search = toAccessorArray( [ NaN, 1.0, 2.0, 3.0 ] );

	out = [ 0 ];
	gsearchSorted( 1, search.length, 'left', toAccessorArray( [ 2.0 ] ), 1, 0, search, 1, 0, toAccessorArray( out ), 1, 0 );
	t.deepEqual( out, [ 2 ], 'returns expected value' );

	out = [ 0 ];
	gsearchSorted( 1, search.length, 'right', toAccessorArray( [ 2.0 ] ), 1, 0, search, 1, 0, toAccessorArray( out ), 1, 0 );
	t.deepEqual( out, [ 3 ], 'returns expected value' );

	search = toAccessorArray( [ 1.0, 2.0, 3.0, NaN ] );

	out = [ 0 ];
	gsearchSorted( 1, search.length, 'left', toAccessorArray( [ 2.0 ] ), 1, 0, search, 1, 0, toAccessorArray( out ), 1, 0 );
	t.deepEqual( out, [ 1 ], 'returns expected value' );

	out = [ 0 ];
	gsearchSorted( 1, search.length, 'right', toAccessorArray( [ 2.0 ] ), 1, 0, search, 1, 0, toAccessorArray( out ), 1, 0 );
	t.deepEqual( out, [ 2 ], 'returns expected value' );

	search = toAccessorArray( [ NaN, NaN ] );

	out = [ 0 ];
	gsearchSorted( 1, search.length, 'left', toAccessorArray( [ 2.0 ] ), 1, 0, search, 1, 0, toAccessorArray( out ), 1, 0 );
	t.deepEqual( out, [ 2 ], 'returns expected value' );

	// Descending order:
	search = toAccessorArray( [ 3.0, NaN, 2.0, 1.0 ] );

	out = [ 0 ];
	gsearchSorted( 1, search.length, 'left', toAccessorArray( [ 2.0 ] ), 1, 0, search, 1, 0, toAccessorArray( out ), 1, 0 );
	t.deepEqual( out, [ 2 ], 'returns expected value' );

	out = [ 0 ];
	gsearchSorted( 1, search.length, 'right', toAccessorArray( [ 2.0 ] ), 1, 0, search, 1, 0, toAccessorArray( out ), 1, 0 );
	t.deepEqual( out, [ 3 ], 'returns expected value' );

	t.end();
});

tape( 'the function treats `-0` and `+0` as equal', function test( t ) {
	var out;

	out = [ 0 ];
	gsearchSorted( 1, 1, 'left', [ -0.0 ], 1, 0, [ 0.0 ], 1, 0, out, 1, 0 );
	t.deepEqual( out, [ 0 ], 'returns expected value' );

	out = [ 0 ];
	gsearchSorted( 1, 1, 'right', [ -0.0 ], 1, 0, [ 0.0 ], 1, 0, out, 1, 0 );
	t.deepEqual( out, [ 1 ], 'returns expected value' );

	out = [ 0 ];
	gsearchSorted( 1, 1, 'left', [ 0.0 ], 1, 0, [ -0.0 ], 1, 0, out, 1, 0 );
	t.deepEqual( out, [ 0 ], 'returns expected value' );

	out = [ 0 ];
	gsearchSorted( 1, 1, 'right', [ 0.0 ], 1, 0, [ -0.0 ], 1, 0, out, 1, 0 );
	t.deepEqual( out, [ 1 ], 'returns expected value' );

	t.end();
});

tape( 'the function supports an `x` stride', function test( t ) {
	var search;
	var out;
	var x;

	x = [
		0.0, // 0
		9.0,
		2.0, // 1
		9.0,
		4.0  // 2
	];
	search = [ 1.0, 2.0, 2.0, 3.0 ];
	out = [ 0, 0, 0 ];

	gsearchSorted( 3, search.length, 'left', x, 2, 0, search, 1, 0, out, 1, 0 );
	t.deepEqual( out, [ 0, 1, 4 ], 'returns expected value' );

	t.end();
});

