tape( 'the function supports negative strides', function test( t ) {
	var search;
	var out;
	var x;

	x = [
		4.0, // 2
		9.0,
		2.0, // 1
		9.0,
		0.0  // 0
	];
	search = [
		3.0, // 3
		9.0,
		2.0, // 2
		9.0,
		2.0, // 1
		9.0,
		1.0  // 0
	];
	out = [
		-1, // 2
		-1,
		-1, // 1
		-1,
		-1  // 0
	];

	gsearchSorted( 3, 4, 'left', x, -2, 4, search, -2, 6, out, -2, 4 );
	t.deepEqual( out, [ 4, -1, 1, -1, 0 ], 'returns expected value' );

	t.end();
});

